class Envelope(_Strict):
    """CloudEvents 1.0 structured envelope with the Pulse extensions."""
    specversion: Literal['1.0']
    id: Annotated[str, Field(pattern='^[0-9A-HJKMNP-TV-Z]{26}$')]
    source: Annotated[str, Field(pattern='^/(collectors|agent|api|edge|system)/[A-Za-z0-9._~/-]+$')]
    type: EventType
    time: datetime
    subject: Annotated[str, Field(pattern='^[a-z_]+:[a-z0-9_]+:.+$')]
    orgid: UUID
    purpose: Annotated[str, Field(pattern='^(delivery|quality|coaching|voice|workload|outcomes|activity_context|after_hours|work_delta|command_counts|wellbeing|presence|office|security|privacy|billing)(,(delivery|quality|coaching|voice|workload|outcomes|activity_context|after_hours|work_delta|command_counts|wellbeing|presence|office|security|privacy|billing))*$')]
    sensitivity: Literal[0, 1, 2]
    visibility: Literal['person', 'team', 'org']
    data: dict[str, Any]
    actor: Annotated[str, Field(pattern='^(person|account|device|system|ai|external):[a-z0-9_]+:.+$')] | None = None
    actorkind: Literal['person', 'account', 'device', 'system', 'ai', 'external'] | None = None
    causationid: str | None = None
    collectorver: Annotated[str, Field(pattern='^[0-9]+\\.[0-9]+\\.[0-9]+')] | None = None
    confidence: Annotated[float, Field(ge=0, le=1)] | None = None
    consentref: Annotated[str, Field(pattern='^(notice|consent):.+$')] | None = None
    correlationid: str | None = None
    datacontenttype: Literal['application/json'] | None = None
    dataschema: Annotated[str, Field(pattern='^schema:[a-z0-9_.]+/[0-9]+$')] | None = None
    project: Annotated[str, Field(pattern='^project:pulse:[0-9a-f-]{36}$')] | None = None
    supersedes: str | None = None

    def typed_data(self) -> _Strict:
        """The data as its registered model (raises pydantic.ValidationError)."""
        return DATA_MODELS[self.type].model_validate(self.data)
